-- ============================================================
-- SEED EXT 2: Módulo 3 — Past Simple (exercícios 71-200)
-- Novos tópicos: irregular verbs avançados, time expressions,
-- used to, narrative, wh-questions, error correction, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'past-simple';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo past-simple não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: irregular verbs group B (speak, break, leave, sleep, etc.)
  (cid,11,71,'gap_fill','She ___ to the professor after class about the assignment. (speak)','spoke',NULL,'Irregular: speak → spoke.','easy'),
  (cid,11,72,'gap_fill','He ___ his leg during the football match. (break)','broke',NULL,'Irregular: break → broke.','easy'),
  (cid,11,73,'gap_fill','They ___ the lab early to catch the train. (leave)','left',NULL,'Irregular: leave → left.','easy'),
  (cid,11,74,'multiple_choice','Past simple of "sleep"?','slept','["sleeped","slept","sleept","sleep"]','Irregular: sleep → slept.','easy'),
  (cid,11,75,'gap_fill','The researcher ___ the results in a spreadsheet. (keep)','kept',NULL,'Irregular: keep → kept.','easy'),
  (cid,11,76,'gap_fill','She ___ the right answer on the exam. (choose)','chose',NULL,'Irregular: choose → chose.','medium'),
  (cid,11,77,'multiple_choice','Past simple of "teach"?','taught','["teached","taught","tought","teachd"]','Irregular: teach → taught.','easy'),
  (cid,11,78,'gap_fill','He ___ through the entire lecture without asking a question. (sit)','sat',NULL,'Irregular: sit → sat.','easy'),
  (cid,11,79,'gap_fill','The professor ___ a new approach to data collection. (build)','built',NULL,'Irregular: build → built.','medium'),
  (cid,11,80,'multiple_choice','Past simple of "buy"?','bought','["buyed","boughted","bought","buied"]','Irregular: buy → bought.','easy'),
  (cid,11,81,'gap_fill','She ___ her research findings at the conference last week. (present)','presented',NULL,'Regular: present → presented.','easy'),
  (cid,11,82,'gap_fill','The wind ___ down several trees during the storm. (blow)','blew',NULL,'Irregular: blow → blew.','medium'),
  (cid,11,83,'multiple_choice','Which past form is IRREGULAR?','caught','["walked","finished","caught","listened"]','Catch → caught (irregular); others are regular -ed verbs.','medium'),

  -- BLOCK 12: time expressions with past simple
  (cid,12,84,'gap_fill','She ___ her degree ___ years ago. (receive)','received / three (or any number)',NULL,'X years ago + past simple.','easy'),
  (cid,12,85,'multiple_choice','Which time expression is used with past simple?','in 2015','["since 2015","for the past year","recently","in 2015"]','Specific finished time (in 2015) → past simple.','medium'),
  (cid,12,86,'gap_fill','___ night, the professor ___ an important announcement. (last / make)','Last / made',NULL,'Last night = specific past time → past simple.','easy'),
  (cid,12,87,'gap_fill','I ___ him ___ week at the conference. (see / last)','saw / last',NULL,'Last week + past simple.','easy'),
  (cid,12,88,'multiple_choice','Which sentence uses a time expression INCORRECTLY with past simple?','I have seen her yesterday.','["I saw her yesterday.","She visited the library last Monday.","He graduated in 2019.","I have seen her yesterday."]','Yesterday requires past simple (saw), not present perfect.','medium'),
  (cid,12,89,'gap_fill','The discovery ___ three decades ___. (happen / ago)','happened / ago',NULL,'X + ago → past simple.','easy'),
  (cid,12,90,'gap_fill','The university ___ its research center ___ 1985. (establish / in)','established / in',NULL,'In + year → past simple.','easy'),
  (cid,12,91,'multiple_choice','Choose the sentence with the CORRECT time expression for past simple:','When I was a student, I studied in the library every night.','["Since I was a student, I studied in the library every night.","For the past year, I studied in the library every night.","When I was a student, I studied in the library every night.","Recently I studied in the library every night."]','When + past continuous/simple → past simple for completed routine.','medium'),
  (cid,12,92,'gap_fill','She ___ an internship at a research lab the year ___. (do / before)','did / before',NULL,'The year before = specific past reference.','medium'),
  (cid,12,93,'gap_fill','Back ___ the 19th century, scientists ___ very little about bacteria. (in / know)','in / knew',NULL,'Back in + time period + knew (past simple).','medium'),

  -- BLOCK 13: past simple vs used to
  (cid,13,94,'gap_fill','She ___ to walk to school every day when she was young. (use)','used',NULL,'Used to + infinitive = past habit no longer done.','easy'),
  (cid,13,95,'multiple_choice','Which sentence expresses a past habit that no longer continues?','She used to live in Brazil, but now she lives in Canada.','["She lived in Brazil last year.","She used to live in Brazil, but now she lives in Canada.","She was living in Brazil last year.","She had lived in Brazil before."]','Used to + base verb = past habit now changed.','medium'),
  (cid,13,96,'gap_fill','Scientists ___ to believe that the Earth was the center of the universe. (use)','used',NULL,'Used to + believe for a past belief that has been corrected.','medium'),
  (cid,13,97,'multiple_choice','Which is WRONG?','Did he used to study here?','["He used to study here.","He didn''t use to study here.","Did he used to study here?","Did he use to study here?"]','Question form: Did + subject + use to (not used to) + base verb.','hard'),
  (cid,13,98,'gap_fill','I ___ (not/use) to enjoy reading, but now I love it.','didn''t use',NULL,'Negative: didn''t + use to (not "didn''t used to").','hard'),
  (cid,13,99,'multiple_choice','What is the difference between "She studied French" and "She used to study French"?','Used to emphasizes a past habit that no longer continues.','["There is no difference.","''Studied'' means she passed; ''used to study'' means she failed.","Used to emphasizes a past habit that no longer continues.","''Studied'' refers to a specific day; ''used to study'' refers to a week."]','Used to = ongoing past habit, now stopped.','hard'),
  (cid,13,100,'gap_fill','The city ___ (use/have) much cleaner air before industrialization.','used to have',NULL,'Used to + have for past state no longer true.','medium'),
  (cid,13,101,'gap_fill','___ you ___ (use/play) video games as a child?','Did / use to play',NULL,'Question: Did + subject + use to + base verb.','hard'),
  (cid,13,102,'multiple_choice','Choose the sentence that is ONLY possible with "used to" (NOT simple past for a single action):','My grandfather used to tell stories about the war every evening.','["She lived here for two years.","My grandfather used to tell stories about the war every evening.","He visited Paris in 1998.","The company opened in 1970."]','Habitual repeated action (every evening) → used to.','hard'),
  (cid,13,103,'gap_fill','There ___ (use/be) a cinema on this street, but it closed years ago.','used to be',NULL,'Used to be for past state/existence no longer true.','medium'),

  -- BLOCK 14: wh-questions in past simple
  (cid,14,104,'gap_fill','___ did she ___ her PhD? (where / do)','Where / do',NULL,'Wh- + did + subject + base verb. Never: Where did she done.','easy'),
  (cid,14,105,'gap_fill','___ did the conference take place? (when)','When',NULL,'When + did + subject + base verb.','easy'),
  (cid,14,106,'multiple_choice','Which past simple wh-question is CORRECT?','Why did the team change their methodology?','["Why the team changed their methodology?","Why did the team changed their methodology?","Why did the team change their methodology?","Why did the team changes their methodology?"]','Why + did + subject + base verb (not past form).','medium'),
  (cid,14,107,'gap_fill','___ published the research on climate change in 2021? (who)','Who',NULL,'Who as subject: Who + past verb (no auxiliary needed). Who published...','hard'),
  (cid,14,108,'multiple_choice','Choose the correct question for: "She wrote the thesis in six months."','How long did it take her to write the thesis?','["How long did she took to write the thesis?","How long it took her to write the thesis?","How long did it take her to write the thesis?","How long took her to write the thesis?"]','How long + did + it + take + object + infinitive.','hard'),
  (cid,14,109,'gap_fill','___ many participants ___ in the study? (how / take part)','How many / took part',NULL,'Who as subject needs no auxiliary; but here: How many + did + verb OR How many + verb (who-subject pattern). Best: How many participants took part (who-type).','hard'),
  (cid,14,110,'gap_fill','___ the professor explain in the last lecture? (what)','What did',NULL,'What + did + subject + base verb for object question.','medium'),
  (cid,14,111,'multiple_choice','For the question "Who discovered DNA structure?", the answer is Watson and Crick. What type of question is this?','Subject question (who = subject of the verb)','["Object question","Subject question (who = subject of the verb)","Wh-question with auxiliary did","Indirect question"]','Who as subject: no auxiliary did; Who discovered = subject question.','hard'),
  (cid,14,112,'gap_fill','___ did the discovery ___ such a significant impact? (why / have)','Why / did / have',NULL,'Why + did + subject + base verb.','medium'),
  (cid,14,113,'gap_fill','___ of the researchers ___ the problem first? (which / notice)','Which / noticed',NULL,'Which + of the + noun = subject question → past verb directly (no did).','hard'),

  -- BLOCK 15: storytelling and narrative past
  (cid,15,114,'gap_fill','She ___ (wake) up early, ___ (have) breakfast, and ___ (leave) for the lab. (narrative)','woke / had / left',NULL,'Three irregular past verbs in sequence.','medium'),
  (cid,15,115,'multiple_choice','Which sequence correctly tells a story using past simple?','She arrived, sat down, opened her notebook, and began to write.','["She arrives, sits down, opens her notebook, and begins to write.","She arrived, sat down, opened her notebook, and began to write.","She has arrived, sat down, opened her notebook, and began to write.","She arrived, was sitting down, opened her notebook, and began to write."]','Past simple for chronological sequence of completed events.','medium'),
  (cid,15,116,'gap_fill','The scientist ___ (enter) the lab, ___ (switch) on the equipment, and ___ (begin) her experiment.','entered / switched / began',NULL,'Three sequential past actions in narrative.','medium'),
  (cid,15,117,'gap_fill','First, the team ___ (collect) the samples. Then, they ___ (analyze) them. Finally, they ___ (write) up the results.','collected / analyzed / wrote',NULL,'Sequence markers (first, then, finally) with past simple.','medium'),
  (cid,15,118,'multiple_choice','In academic historical narrative, which connector best introduces the SECOND event in a sequence?','Subsequently','["However","Subsequently","Although","Therefore"]','Subsequently = after that, for chronological sequence.','medium'),
  (cid,15,119,'production','[Writing — narrative] Write 4 sentences describing a historical scientific discovery using past simple. Include: who made it, when, what they did, and what happened as a result.','',NULL,'In 1928, Alexander Fleming noticed mold growing on a bacterial culture. He examined the sample and discovered that the mold killed surrounding bacteria. He named the active substance penicillin. This discovery transformed modern medicine.','medium'),
  (cid,15,120,'gap_fill','After years of research, Darwin ___ (publish) "On the Origin of Species" in 1859. The book ___ (change) scientific thinking forever.','published / changed',NULL,'Two past simple verbs in academic historical narrative.','easy'),
  (cid,15,121,'multiple_choice','Which sentence BEST uses past simple for academic historical writing?','Scientists first isolated the HIV virus in 1983.','["Scientists have isolated the HIV virus in 1983.","Scientists were first isolated the HIV virus in 1983.","Scientists first isolated the HIV virus in 1983.","Scientists are first isolated the HIV virus in 1983."]','In + year → past simple for historical event.','easy'),
  (cid,15,122,'gap_fill','The industrial revolution ___ (begin) in Britain in the late 18th century and ___ (spread) to Europe and North America.','began / spread',NULL,'Irregular past: begin → began, spread → spread.','medium'),
  (cid,15,123,'gap_fill','Newton ___ (sit) under a tree when an apple ___ (fall) and ___ (inspire) his theory of gravity.','sat / fell / inspired',NULL,'Past continuous (was sitting) + past simple for interruption. But traditionally: sat + fell + inspired.','hard'),

  -- BLOCK 16: error correction
  (cid,16,124,'multiple_choice','Find and correct the error: "She goed to the conference yesterday."','goed → went','["conference → conferences","She → He","yesterday → last day","goed → went"]','Go is irregular: go → went (not goed).','easy'),
  (cid,16,125,'gap_fill','Error: "He didn''t wrote the report." → Correct: "He didn''t ___ the report."','write',NULL,'Negative past: didn''t + base verb (not past form).','easy'),
  (cid,16,126,'multiple_choice','Which sentence contains an error?','Did she understood the instructions?','["She didn''t understand the instructions.","Did she understand the instructions?","She understood the instructions.","Did she understood the instructions?"]','Did + base verb (not past): Did she understand (not understood).','easy'),
  (cid,16,127,'gap_fill','Error: "The researchers has published their findings last year." → Correct: "The researchers ___ their findings last year."','published',NULL,'Last year = specific past time → past simple (not present perfect).','medium'),
  (cid,16,128,'multiple_choice','Which sentence is CORRECT?','She wrote three papers during her PhD.','["She has written three papers during her PhD.","She wrote three papers during her PhD.","She writes three papers during her PhD.","She had written three papers during her PhD (without additional past context)."]','During her PhD (finished period) → past simple.','hard'),
  (cid,16,129,'gap_fill','Error: "When did she left?" → Correct: "When did she ___?"','leave',NULL,'Wh-question: did + base verb (not past form).','easy'),
  (cid,16,130,'multiple_choice','Find the error: "Yesterday, we discussed the results and have decided on the next steps."','have decided → decided','["Yesterday → Last day","discussed → have discussed","have decided → decided","results → result"]','Yesterday requires past simple: decided (not present perfect).','medium'),
  (cid,16,131,'gap_fill','Error correction: "The team builded a new laboratory last year." → Correct: "The team ___ a new laboratory last year."','built',NULL,'Build is irregular: built (not builded).','easy'),
  (cid,16,132,'multiple_choice','Choose the sentence WITHOUT errors:','The professor spent three years writing the textbook.','["The professor spend three years writing the textbook.","The professor spended three years writing the textbook.","The professor spent three years writing the textbook.","The professor spending three years writing the textbook."]','Spend → spent (irregular).','easy'),
  (cid,16,133,'gap_fill','Error: "Did the study prooved the hypothesis?" → Correct: "Did the study ___ the hypothesis?"','prove',NULL,'Did + base verb: prove (not proved/prooved).','easy'),
  (cid,16,134,'multiple_choice','Which error appears in: "She use to study at night, but now she prefers mornings."?','use should be used (in affirmative used to)','["she should be her","use should be used (in affirmative used to)","study should be studies","but should be however"]','Affirmative: used to (not use to).','medium'),

  -- BLOCK 17: TOEFL Reading — historical academic texts
  (cid,17,135,'multiple_choice','[TOEFL Reading] "In the 18th century, Linnaeus classified organisms into distinct taxonomic groups." Which tense and why?','Past simple — specific finished action in named historical period.','["Present simple — scientific fact","Present perfect — recent relevance","Past simple — specific finished action in named historical period.","Past continuous — background information"]','In the 18th century = specific past → past simple.','medium'),
  (cid,17,136,'gap_fill','[TOEFL Reading] "Mendel ___ (conduct) his famous experiments with pea plants between 1856 and 1863." Fill the blank.','conducted',NULL,'Specific time range in the past → past simple.','easy'),
  (cid,17,137,'multiple_choice','[TOEFL Reading] In a passage about the fall of the Roman Empire, which tense dominates the narrative?','Past simple','["Present simple","Present perfect","Past simple","Future simple"]','Historical events = past simple.','easy'),
  (cid,17,138,'gap_fill','[TOEFL Reading] "The First World War ___ (begin) in 1914 and ___ (end) in 1918, ___ (claim) approximately 17 million lives." Fill all three blanks.','began / ended / claiming',NULL,'Began + ended (past simple) + claiming (present participle in absolute clause).','hard'),
  (cid,17,139,'multiple_choice','[TOEFL Reading] "Watson and Crick published their model of DNA in 1953, having relied heavily on Franklin''s X-ray data." Why is "published" in past simple?','It refers to a specific completed event in a named year.','["It refers to a currently relevant discovery","It describes a background action","It refers to a specific completed event in a named year.","It expresses a past habit"]','In 1953 = specific time → past simple.','medium'),
  (cid,17,140,'gap_fill','[TOEFL Reading] "Scientists ___ (initially/believe) that the universe was static until Hubble''s observations in 1929 ___ (reveal) otherwise."','initially believed / revealed',NULL,'Past simple for historical belief and discovery.','hard'),
  (cid,17,141,'multiple_choice','[TOEFL Reading] A passage uses past simple throughout to describe a historical period. One sentence switches to present simple: "Today, historians view this event as a turning point." Why?','To contrast past events with a current academic perspective.','["A grammar error in the passage","To introduce a future prediction","To contrast past events with a current academic perspective.","To describe a permanent scientific fact"]','Past narrative → present simple for current scholarly view.','hard'),
  (cid,17,142,'gap_fill','[TOEFL Reading] "The printing press ___ (revolutionize) the spread of information in 15th-century Europe." Fill the blank.','revolutionized',NULL,'In 15th century = specific past → past simple.','easy'),
  (cid,17,143,'multiple_choice','[TOEFL Reading] "During the Great Depression, millions of Americans lost their jobs and struggled to survive." The past simple "lost" and "struggled" describe:','Completed states and actions within a defined historical period.','["Ongoing actions in the present","Future predictions","Completed states and actions within a defined historical period.","Habitual past actions with no known endpoint"]','Defined period (The Great Depression) → past simple.','medium'),
  (cid,17,144,'gap_fill','[TOEFL Reading] "Newton ___ (formulate) the laws of motion in the 1680s, though his ideas ___ (not/gain) widespread acceptance for decades."','formulated / did not gain',NULL,'Past simple + negative past simple.','medium'),
  (cid,17,145,'multiple_choice','[TOEFL Reading] "Although early psychologists dismissed unconscious processes, Freud argued that they fundamentally shaped human behavior." Which best describes the grammar?','Past simple for historical academic positions.','["Present perfect for both verbs","Past simple for one and present for the other","Past simple for historical academic positions.","Present simple for general truth"]','Dismissed + argued = both past simple for historical positions.','hard'),
  (cid,17,146,'gap_fill','[TOEFL Reading] "The Berlin Wall ___ (fall) in 1989, ___ (mark) the end of the Cold War era."','fell / marking',NULL,'Fell (past simple) + marking (present participle for simultaneous result).','hard'),
  (cid,17,147,'multiple_choice','[TOEFL Reading] "Early astronomers believed the Earth was flat." This sentence implies:','This was their belief in the past; it is no longer accepted.','["Astronomers still believe this today","This belief was correct","This was their belief in the past; it is no longer accepted.","Astronomers discovered the Earth was flat recently"]','Past simple for belief no longer held.','medium'),

  -- BLOCK 18: TOEFL Listening
  (cid,18,148,'multiple_choice','[TOEFL Listening] The professor says: "So last semester we focused on the Renaissance. Today we''ll move to the Baroque period." What tense does "focused" use and why?','Past simple — last semester is a specific completed past period.','["Present perfect — still relevant","Past simple — last semester is a specific completed past period.","Past continuous — ongoing at the time","Present simple — general academic fact"]','Last semester = specific past time → past simple.','easy'),
  (cid,18,149,'gap_fill','[TOEFL Listening] "The professor mentioned that Darwin ___ (spend) five years on the Beagle voyage before developing his theory of natural selection." Fill the blank.','spent',NULL,'Specific duration in the past → past simple.','easy'),
  (cid,18,150,'multiple_choice','[TOEFL Listening] A student asks: "Did the researchers find any significant results?" The professor replies: "They found a moderate correlation." Which tense appears in both?','Past simple','["Present perfect in both","Past simple","Present simple in question, past simple in answer","Past simple in question, present perfect in answer"]','Did find + found = both past simple.','easy'),
  (cid,18,151,'gap_fill','[TOEFL Listening] "When Columbus ___ (arrive) in the Americas in 1492, he ___ (believe) he had reached Asia." Fill both blanks.','arrived / believed',NULL,'Past simple for two simultaneous past events.','medium'),
  (cid,18,152,'multiple_choice','[TOEFL Listening] The professor says: "Flemming noticed the mold and immediately realized its potential." This sentence uses past simple to:','Describe a rapid sequence of completed past events.','["Describe ongoing background events","Describe a rapid sequence of completed past events.","Describe a future plan","Describe a habitual past routine"]','Noticed + realized = sequence of completed actions.','medium'),
  (cid,18,153,'gap_fill','[TOEFL Listening] "The lecture ___ (cover) four main topics: climate change, biodiversity, carbon emissions, and international policy."','covered',NULL,'Past simple for a completed lecture.','easy'),
  (cid,18,154,'multiple_choice','[TOEFL Listening] A professor says: "Some historians argued that the war was inevitable." What does the past simple "argued" suggest?','This was the historians'' position at a past time (possibly changed).','["Historians currently argue this","Historians will argue this","This was the historians'' position at a past time (possibly changed).","Historians have proven this"]','Argued = past position, may differ from current view.','hard'),

  -- BLOCK 19: TOEFL Speaking production
  (cid,19,155,'production','[TOEFL Speaking — 45s] Describe a significant historical event you have studied. Use past simple throughout. Include: when it happened, what caused it, what people did, and what the outcome was.','',NULL,'The Industrial Revolution began in the late 18th century... Inventors developed steam-powered machines... Workers moved from rural areas to cities... This transformed economic and social structures worldwide.','hard'),
  (cid,19,156,'production','[TOEFL Speaking — 45s] Describe a personal academic experience using past simple (e.g., studying for an important exam, completing a research project, giving a presentation). Include sequence markers: first, then, after that, finally.','',NULL,'First, I planned my research... Then I collected my data... After that, I analyzed the results... Finally, I submitted my paper on time.','medium'),
  (cid,19,157,'production','[TOEFL Speaking — 45s] Using "used to," compare academic life in the past (before the internet) with academic life today. Include at least 3 "used to" structures and contrast with present simple.','',NULL,'Students used to rely on physical libraries... Researchers used to wait months for journals... Communication used to be much slower... Now, information is instantly accessible.','hard'),
  (cid,19,158,'production','[TOEFL Speaking — 45s] Summarize a scientific discovery: who made it, what they did step by step, and why it matters. Use past simple for the discovery narrative.','',NULL,'Marie Curie discovered radium in 1898. She isolated radioactive isotopes from pitchblende. She published her findings despite opposition. Her work laid the foundation for nuclear medicine.','hard'),
  (cid,19,159,'production','[TOEFL Speaking — 45s] Describe a major change in your country or field of study over the past century. Use: used to (past state), past simple (key events), and present simple (current situation).','',NULL,'A century ago, education used to be limited to the elite. Reforms in the mid-20th century expanded access. The government invested heavily in public schools. Today, education is compulsory for all children.','hard'),

  -- BLOCK 20: TOEFL Writing production
  (cid,20,160,'production','[TOEFL Writing] Write a 5-sentence paragraph about a historical scientific discovery using past simple throughout. Include: who, when, what was done, what was discovered, and its impact.','',NULL,'In 1928, Alexander Fleming accidentally discovered penicillin. He observed that mold killed surrounding bacteria. Fleming isolated the active compound and published his findings. His discovery eventually saved millions of lives. The development of antibiotics transformed modern healthcare.','hard'),
  (cid,20,161,'production','[TOEFL Writing — Error Correction] Correct all errors: "Newton have developed calculus in the 1660s. He didn''t published his work immediately. When Leibniz also developed calculus, a dispute begin. Both mathematicians claimed credit."','',NULL,'developed (not have developed); didn''t publish (base verb); began (irregular); claimed (correct already).','hard'),
  (cid,20,162,'production','[TOEFL Writing] Write a body paragraph about the Industrial Revolution. Use: past simple for events and changes, "used to" for pre-industrial life, and time expressions (in the 18th century, by 1850, within decades).','',NULL,'Before industrialization, most people used to work on farms... The first factories appeared in Britain in the 1760s... By 1850, steam engines powered transportation... Workers moved to cities within decades...','hard'),
  (cid,20,163,'production','[TOEFL Writing — 150 words] Agree or disagree: "The most important inventions in human history happened before the 20th century." Use past simple to support your argument with specific historical examples.','',NULL,'Gutenberg invented the printing press in 1440... Newton formulated the laws of motion in 1687... James Watt developed the steam engine in 1769... Edison created the phonograph and the light bulb... These inventions transformed civilization...','hard'),
  (cid,20,164,'production','[TOEFL Writing] Write a 5-sentence introduction paragraph for an essay on colonialism using past simple. Include: background context, key historical events, a significant turning point, consequences, and a thesis statement.','',NULL,'European powers began colonizing Africa, Asia, and the Americas from the 15th century. They established trade routes, exploited natural resources, and imposed political control. The Berlin Conference of 1884 divided Africa among European nations. Colonial rule lasted for centuries and left lasting social and economic consequences. This essay argues that the legacy of colonialism continues to shape global inequality today.','hard'),

  -- BLOCK 21: mixed advanced
  (cid,21,165,'multiple_choice','Which sentence uses past simple and present perfect CORRECTLY together?','Scientists discovered the vaccine in 2020, and since then, millions have been vaccinated.','["Scientists have discovered the vaccine in 2020, and since then, millions were vaccinated.","Scientists discovered the vaccine in 2020, and since then, millions have been vaccinated.","Scientists discovered the vaccine in 2020, and since then, millions vaccinated.","Scientists have discovered the vaccine in 2020, and millions have been vaccinated."]','Discovered (specific year = past simple) + have been vaccinated (since then = present perfect).','hard'),
  (cid,21,166,'gap_fill','By the time she ___ (finish) her PhD, she ___ (publish) five papers.','finished / had published',NULL,'By the time + past simple → past perfect for prior action.','hard'),
  (cid,21,167,'multiple_choice','Choose the most academically appropriate historical sentence:','During the Enlightenment, philosophers challenged religious authority and advocated for reason.','["During the Enlightenment, philosophers have challenged religious authority.","During the Enlightenment, philosophers are challenging religious authority.","During the Enlightenment, philosophers challenged religious authority and advocated for reason.","During the Enlightenment, philosophers challenge religious authority and advocate for reason."]','Historical period + past simple.','medium'),
  (cid,21,168,'gap_fill','[TOEFL] "The experiment ___ (fail) because the researchers ___ (not/control) for confounding variables."','failed / did not control',NULL,'Past simple + negative past simple for cause and effect.','medium'),
  (cid,21,169,'multiple_choice','In a TOEFL essay about historical events, which combination is MOST common?','Past simple for narrative events + present simple for evaluation/argument','["Past simple only","Present simple only","Past simple for narrative events + present simple for evaluation/argument","Present perfect throughout"]','Historical essays: past simple for what happened, present simple for the author''s current evaluation.','hard'),
  (cid,21,170,'production','[TOEFL — Synthesis Task] You read that: (A) The Scientific Revolution of the 17th century laid the foundations for modern science; (B) Ancient Greek philosophers also made essential contributions. Write a 4-sentence synthesis using past simple and used to to present both perspectives.','',NULL,'During the 17th century, scientists like Newton and Galileo developed modern empirical methods... Ancient Greek philosophers used to rely on reason and observation rather than experiment... However, thinkers like Aristotle laid important conceptual groundwork... Both traditions contributed to our understanding of the natural world.','hard'),

  -- BLOCK 22: production and integration
  (cid,22,171,'production','[TOEFL Speaking — 45s] Tell the story of how you became interested in English or TOEFL preparation. Use past simple and "used to" for at least 5 verbs.','',NULL,'I used to struggle with English at school... Then I started watching American films... I decided to take the TOEFL when I wanted to study abroad... My first practice test went badly, but I didn''t give up...','medium'),
  (cid,22,172,'production','[TOEFL Writing] Write 5 subject questions (questions where "who" or "what" is the subject) about historical events in past simple.','',NULL,'Who discovered America in 1492? What caused the fall of the Roman Empire? Which scientist first split the atom? Who invented the telephone? What ended the Second World War?','hard'),
  (cid,22,173,'gap_fill','[TOEFL] "Although the expedition ___ (face) enormous challenges, it ___ (ultimately/succeed) in mapping the coastline."','faced / ultimately succeeded',NULL,'Past simple + adverb placement in formal sentence.','medium'),
  (cid,22,174,'multiple_choice','[TOEFL] Which sentence BEST uses past simple to show contrast in academic writing?','Early economists viewed markets as self-regulating, whereas Keynesian economists argued for government intervention.','["Early economists view markets as self-regulating, whereas Keynesian economists argue for intervention.","Early economists viewed markets as self-regulating, whereas Keynesian economists argued for government intervention.","Early economists have viewed markets as self-regulating.","Early economists are viewing markets differently than Keynesian economists."]','Viewed + argued = past simple for contrasting historical positions.','hard'),
  (cid,22,175,'production','[TOEFL Writing — 200 words] Write a paragraph arguing for or against this statement: "The 20th century produced more significant scientific advances than all previous centuries combined." Use past simple for historical evidence and specific examples.','',NULL,'The 20th century witnessed extraordinary scientific breakthroughs... Physicists split the atom and developed quantum mechanics... Watson and Crick discovered the structure of DNA in 1953... Neil Armstrong walked on the Moon in 1969... Fleming discovered penicillin, saving millions of lives... However, Newton, Darwin, Galileo, and Copernicus revolutionized human understanding in earlier centuries...','hard'),

  -- BLOCK 23: final challenging tasks
  (cid,23,176,'gap_fill','[TOEFL] "Darwin ___ (observe) significant variation among species during his voyage on the Beagle, which ___ (lead) him to question the prevailing view that species ___ (be) fixed and unchanging."','observed / led / were',NULL,'Three past simple verbs in academic historical narrative.','hard'),
  (cid,23,177,'multiple_choice','[TOEFL Writing] A student writes: "Columbus has discovered America in 1492." The teacher marks this wrong. Why?','In 1492 is a specific past time — past simple required, not present perfect.','["America is not a country","Columbus is spelled incorrectly","In 1492 is a specific past time — past simple required, not present perfect.","Has discovered is acceptable in formal writing"]','Specific year → past simple.','easy'),
  (cid,23,178,'gap_fill','[TOEFL] "Not until the 19th century ___ scientists ___ to understand the mechanisms of infectious disease." (begin)','did / begin',NULL,'Inverted past simple with negative adverb: Not until + did + subject + base verb.','hard'),
  (cid,23,179,'production','[TOEFL Speaking — 45s] You have 45 seconds to respond: A professor argues that the printing press was the most transformative invention in human history. Do you agree? Use past simple to support your position with historical evidence.','',NULL,'The printing press revolutionized the dissemination of knowledge... It enabled the Reformation and accelerated the Scientific Revolution... Literacy rates rose dramatically after its introduction... However, one could also argue that the internet similarly transformed communication in the 20th century...','hard'),
  (cid,23,180,'production','[TOEFL Writing — Capstone] Write a 200-word argumentative paragraph on ONE of the following historical turning points: (A) The French Revolution, (B) The Industrial Revolution, (C) The Digital Revolution. Use past simple as the dominant tense, but include present simple for your thesis and current relevance.','',NULL,'The Industrial Revolution began in Britain in the late 18th century and fundamentally changed human society... Factories replaced artisan workshops... Workers migrated from rural areas to industrial cities... Child labor became widespread before reform movements challenged it... Wealth inequality grew dramatically... Today, historians view this period as the foundation of modern capitalism... This suggests that technological progress always entails both opportunity and inequality.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
